+          id: 'a1',
+          name: 'a1',
+          agentType: 'task',
+          task: 't',
+        );
+        await manager.update('a1', status: SubagentStatus.completed);
+        await fabric.send(
+          AgentMessage(
+            id: 'm1',
+            fromId: 'x',
+            toId: manager.mailboxOf('a1'),
+            text: 'hello',
+            sentAt: '2026-09-26T10:00:00Z',
