+      };
+      await fabric.send(
+        AgentMessage(
+          id: 'm1',
+          fromId: 'x',
+          toId: manager.mailboxOf('a1'),
+          text: 'tick one',
+          sentAt: '2026-09-26T10:00:00Z',
+        ),
+      );
+      expect(await manager.wakeChildrenWithPendingMail(), 1);
+      await Future<void>.delayed(Duration.zero);
