+      await fabric.send(
+        AgentMessage(
+          id: 'm2',
+          fromId: 'x',
+          toId: manager.mailboxOf('a1'),
+          text: 'tick two',
+          sentAt: '2026-09-26T10:15:00Z',
+        ),
