 /// blocking-batch spawn (queued on the semaphore or running) or an
 /// in-flight resume.
 bool isInFlight(String id) =>
     _currentSubagentIds.contains(id) ||
     _resumesInFlight.contains(id) ||
     _inFlightCancels.containsKey(id);

