List<AgentTool> subagentMonitoringTools({
  required SubagentManager? manager,
  ChildMessageReader? readMessages,
  ChildResumeRunner? resumeChild,
  CurrentSubagentIdProvider? currentSubagentId,
  TaskJobManager? jobs,
